steps.script:
return {
  url: location.href,
  title: document.title,
  readyState: document.readyState,
  loginFields: {
    userExists: !!document.querySelector('#vUSER'),
    passwordExists: !!document.querySelector('#vUSRPSWING'),
    confirmExists: !!document.querySelector('#BTNENTER'),
    userVisible: !!(document.querySelector('#vUSER')?.offsetWidth || document.querySelector('#vUSER')?.offsetHeight || document.querySelector('#vUSER')?.getClientRects().length),
    passwordVisible: !!(document.querySelector('#vUSRPSWING')?.offsetWidth || document.querySelector('#vUSRPSWING')?.offsetHeight || document.querySelector('#vUSRPSWING')?.getClientRects().length),
    confirmVisible: !!(document.querySelector('#BTNENTER')?.offsetWidth || document.querySelector('#BTNENTER')?.offsetHeight || document.querySelector('#BTNENTER')?.getClientRects().length)
  },
  forms: [...document.forms].map(f => ({
    id: f.id,
    name: f.name,
    method: f.method,
    action: f.getAttribute('action'),
    target: f.target,
    inputCount: f.querySelectorAll('input,textarea,select,button').length
  })),
  hiddenControls: [...document.querySelectorAll('input[type="hidden"]')].slice(0, 80).map(e => ({
    id: e.id,
    name: e.name,
    type: e.type,
    valueLength: String(e.value || '').length,
    hasValue: String(e.value || '').length > 0
  }))
};

const user = document.querySelector('#vUSER');
const pass = document.querySelector('#vUSRPSWING');
const btn = document.querySelector('#BTNENTER');
return {
  url: location.href,
  activeElement: {
    tag: document.activeElement?.tagName,
    id: document.activeElement?.id,
    name: document.activeElement?.getAttribute('name'),
    type: document.activeElement?.getAttribute('type')
  },
  user: {
    exists: !!user,
    visible: !!(user?.offsetWidth || user?.offsetHeight || user?.getClientRects().length),
    valueLength: String(user?.value || '').length,
    hasValue: String(user?.value || '').length > 0
  },
  password: {
    exists: !!pass,
    visible: !!(pass?.offsetWidth || pass?.offsetHeight || pass?.getClientRects().length),
    valueLength: String(pass?.value || '').length,
    hasValue: String(pass?.value || '').length > 0
  },
  confirm: {
    exists: !!btn,
    visible: !!(btn?.offsetWidth || btn?.offsetHeight || btn?.getClientRects().length),
    disabled: !!btn?.disabled,
    value: btn?.value || btn?.innerText || ''
  }
};

return {
  url: location.href,
  title: document.title,
  readyState: document.readyState,
  loginVisible: !!(document.querySelector('#vUSER')?.offsetWidth || document.querySelector('#vUSER')?.offsetHeight || document.querySelector('#vUSER')?.getClientRects().length),
  passwordVisible: !!(document.querySelector('#vUSRPSWING')?.offsetWidth || document.querySelector('#vUSRPSWING')?.offsetHeight || document.querySelector('#vUSRPSWING')?.getClientRects().length),
  confirmVisible: !!(document.querySelector('#BTNENTER')?.offsetWidth || document.querySelector('#BTNENTER')?.offsetHeight || document.querySelector('#BTNENTER')?.getClientRects().length),
  menuCandidateCount: document.querySelectorAll('[id*="gxui"], [class*="gxui"], [id*="menu"], [class*="menu"]').length,
  bodyTextStart: document.body?.innerText?.replace(/\s+/g, ' ').trim().slice(0, 300) || ''
};

const visible = (e) => !!(e && (e.offsetWidth || e.offsetHeight || e.getClientRects().length));
const textOf = (e) => String(e?.innerText || e?.value || e?.textContent || '').replace(/\s+/g, ' ').trim();
const candidates = [...document.querySelectorAll('a,button,input,[role="button"],[onclick],[id*="gxui"],[class*="gxui"],[id*="menu"],[class*="menu"],[id*="toolbar"],[class*="toolbar"]')]
  .map((e, index) => ({
    index,
    tag: e.tagName,
    id: e.id || '',
    name: e.getAttribute('name') || '',
    type: e.getAttribute('type') || '',
    role: e.getAttribute('role') || '',
    className: String(e.className || '').slice(0, 200),
    text: textOf(e).slice(0, 200),
    visible: visible(e),
    disabled: !!e.disabled,
    rect: (() => {
      const r = e.getBoundingClientRect();
      return { x: Math.round(r.x), y: Math.round(r.y), width: Math.round(r.width), height: Math.round(r.height) };
    })()
  }))
  .filter(x => x.visible || x.text || x.id)
  .slice(0, 200);

const loginUser = document.querySelector('#vUSER');
const loginPassword = document.querySelector('#vUSRPSWING');

return {
  url: location.href,
  title: document.title,
  readyState: document.readyState,
  isLoginPage: !!loginUser || !!loginPassword || /Usuario|Password/i.test(document.body?.innerText || ''),
  loginFieldState: {
    userExists: !!loginUser,
    userVisible: visible(loginUser),
    userValueLength: String(loginUser?.value || '').length,
    userHasValue: String(loginUser?.value || '').length > 0,
    passwordExists: !!loginPassword,
    passwordVisible: visible(loginPassword),
    passwordValueLength: String(loginPassword?.value || '').length,
    passwordHasValue: String(loginPassword?.value || '').length > 0
  },
  possibleErrorTexts: [...document.querySelectorAll('body *')]
    .map(e => textOf(e))
    .filter(t => t && /error|incorrect|invalid|invalido|inválido|senha|password|usuario|usuário|login|denegado|rechazado|fall[oó]|failed/i.test(t))
    .slice(0, 50),
  forms: [...document.forms].map(f => ({
    id: f.id,
    name: f.name,
    method: f.method,
    action: f.getAttribute('action'),
    target: f.target,
    inputCount: f.querySelectorAll('input,textarea,select,button').length
  })),
  visibleActionCandidates: candidates,
  bodyText: (document.body?.innerText || '').replace(/\s+/g, ' ').trim().slice(0, 3000)
};
